CREATE OR REPLACE FUNCTION minicore.fn_update_account_balance()
RETURNS TRIGGER AS $$
DECLARE
    v_code        NUMERIC(5);
    v_amount      NUMERIC(18,2);
    v_sign        SMALLINT;
    v_avail_delta NUMERIC(18,2);
    v_coll_delta  NUMERIC(18,2);
    v_available   NUMERIC(18,2);
    v_collected   NUMERIC(18,2);
BEGIN
    IF NEW.original_transaction_id IS NOT NULL AND NEW.status = 'POSTED' THEN
        -- Confirmation of a PENDING: balance already applied, just snapshot
        SELECT available_balance, collected_balance
        INTO v_available, v_collected
        FROM minicore.accounts
        WHERE account_id = NEW.account_id;
    ELSE
        IF NEW.original_transaction_id IS NOT NULL AND NEW.status = 'CANCELLED' THEN
            -- Cancellation: reverse the ORIGINAL transaction's balance effects
            SELECT transaction_code, amount
            INTO v_code, v_amount
            FROM minicore.transactions
            WHERE transaction_id = NEW.original_transaction_id;
            v_sign := -1;
        ELSE
            -- Born transaction (PENDING or POSTED): apply effects normally
            v_code := NEW.transaction_code;
            v_amount := NEW.amount;
            v_sign := 1;
        END IF;

        -- Compute balance deltas from transaction_code_balance_effects
        SELECT
            COALESCE(SUM(CASE WHEN e.balance_name = 'AVAILABLE' THEN v_sign * v_amount * e.effect END), 0),
            COALESCE(SUM(CASE WHEN e.balance_name = 'COLLECTED' THEN v_sign * v_amount * e.effect END), 0)
        INTO v_avail_delta, v_coll_delta
        FROM minicore.transaction_code_balance_effects e
        WHERE e.transaction_code = v_code;

        -- Apply deltas
        UPDATE minicore.accounts
        SET available_balance = available_balance + v_avail_delta,
            collected_balance = collected_balance + v_coll_delta,
            updated_at = NOW()
        WHERE account_id = NEW.account_id
        RETURNING available_balance, collected_balance
        INTO v_available, v_collected;
    END IF;

    -- Record post-transaction balance snapshot
    INSERT INTO minicore.transaction_balances
        (transaction_id, account_id, available_balance, collected_balance)
    VALUES
        (NEW.transaction_id, NEW.account_id, v_available, v_collected);

    RETURN NEW;
END;
$$ LANGUAGE plpgsql

CREATE OR REPLACE FUNCTION minicore.fn_outbox_transactions()
RETURNS TRIGGER AS $$
BEGIN
    INSERT INTO minicore.outbox_transactions
        (operation_type, transaction_id, account_id, original_transaction_id, transaction_code, amount, direction, status, json_payload, effective_date, created_by, created_at)
    VALUES
        ('INSERT', NEW.transaction_id, NEW.account_id, NEW.original_transaction_id, NEW.transaction_code, NEW.amount, NEW.direction, NEW.status, NEW.json_payload, NEW.effective_date, NEW.created_by, NEW.created_at);
    RETURN NEW;
END;
$$ LANGUAGE plpgsql

CREATE OR REPLACE FUNCTION minicore.fn_populate_accounts_sync_wait_confirmation()
RETURNS TRIGGER AS $$
BEGIN
    INSERT INTO minicore.outbox_accounts_sync_wait_confirmation (event_id, bulk_id)
    SELECT event_id, NEW.bulk_id
    FROM minicore.outbox_accounts
    WHERE event_id BETWEEN NEW.first_event_id AND NEW.last_event_id;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql

CREATE OR REPLACE FUNCTION minicore.fn_populate_transactions_sync_wait_confirmation()
RETURNS TRIGGER AS $$
BEGIN
    INSERT INTO minicore.outbox_transactions_sync_wait_confirmation (event_id, bulk_id)
    SELECT event_id, NEW.bulk_id
    FROM minicore.outbox_transactions
    WHERE event_id BETWEEN NEW.first_event_id AND NEW.last_event_id;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql

CREATE OR REPLACE FUNCTION minicore.fn_cleanup_accounts_sync_wait_confirmation()
RETURNS TRIGGER AS $$
BEGIN
    DELETE FROM minicore.outbox_accounts_sync_wait_confirmation
    WHERE event_id = NEW.event_id;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql

CREATE OR REPLACE FUNCTION minicore.fn_cleanup_transactions_sync_wait_confirmation()
RETURNS TRIGGER AS $$
BEGIN
    DELETE FROM minicore.outbox_transactions_sync_wait_confirmation
    WHERE event_id = NEW.event_id;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql

CREATE OR REPLACE FUNCTION minicore.fn_validate_transaction_lifecycle()
RETURNS TRIGGER AS $$
DECLARE
    v_orig_status  minicore.transaction_status_enum;
    v_orig_parent  BIGINT;
    v_orig_account BIGINT;
BEGIN
    IF NEW.original_transaction_id IS NOT NULL THEN
        -- Look up the original transaction
        SELECT status, original_transaction_id, account_id
        INTO v_orig_status, v_orig_parent, v_orig_account
        FROM minicore.transactions
        WHERE transaction_id = NEW.original_transaction_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Original transaction % does not exist', NEW.original_transaction_id;
        END IF;

        -- Original must be a born PENDING (not itself a modifier)
        IF v_orig_status != 'PENDING' THEN
            RAISE EXCEPTION 'Can only confirm/cancel PENDING transactions (original % is %)',
                NEW.original_transaction_id, v_orig_status;
        END IF;

        IF v_orig_parent IS NOT NULL THEN
            RAISE EXCEPTION 'Cannot modify a modifier transaction (original % is itself a modifier)',
                NEW.original_transaction_id;
        END IF;

        -- Must target the same account
        IF v_orig_account != NEW.account_id THEN
            RAISE EXCEPTION 'Modifier account_id (%) must match original account_id (%)',
                NEW.account_id, v_orig_account;
        END IF;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql

CREATE OR REPLACE FUNCTION minicore.fn_prevent_transaction_update()
RETURNS TRIGGER AS $$
BEGIN
    RAISE EXCEPTION 'Transactions are immutable and cannot be updated';
END;
$$ LANGUAGE plpgsql

CREATE OR REPLACE FUNCTION minicore.fn_check_effect_consistency()
RETURNS TRIGGER AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM minicore.transaction_code_balance_effects
        WHERE transaction_code = NEW.transaction_code
          AND effect != NEW.effect
    ) THEN
        RAISE EXCEPTION 'Transaction code % cannot have opposite signs for different balances', NEW.transaction_code;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql
